package com.aicharacter.v3;
import org.json.*;import java.util.*;
public final class DiaryEntry {public final String diaryId;public long time;public String text,mood,reflectionType;public final List<String> sourceMemoryIds=new ArrayList<>(),sourceBeliefIds=new ArrayList<>(),relatedPlaceIds=new ArrayList<>(),relatedCreatureIds=new ArrayList<>();
 public DiaryEntry(long t,String text){this(IdFactory.next("diary"),t,text,"","reflection");}public DiaryEntry(String id,long t,String text,String mood,String type){diaryId=(id==null||id.isEmpty())?IdFactory.next("diary"):id;time=t;this.text=text;this.mood=mood;reflectionType=type;}
 public JSONObject toJson()throws JSONException{JSONObject j=new JSONObject();j.put("diaryId",diaryId);j.put("time",time);j.put("text",text);j.put("mood",mood);j.put("reflectionType",reflectionType);j.put("sourceMemoryIds",new JSONArray(sourceMemoryIds));j.put("sourceBeliefIds",new JSONArray(sourceBeliefIds));j.put("relatedPlaceIds",new JSONArray(relatedPlaceIds));j.put("relatedCreatureIds",new JSONArray(relatedCreatureIds));return j;}
 public static DiaryEntry fromJson(JSONObject j){DiaryEntry d=new DiaryEntry(j.optString("diaryId",IdFactory.next("diary")),j.optLong("time"),j.optString("text"),j.optString("mood"),j.optString("reflectionType","legacy"));read(j,"sourceMemoryIds",d.sourceMemoryIds);read(j,"sourceBeliefIds",d.sourceBeliefIds);read(j,"relatedPlaceIds",d.relatedPlaceIds);read(j,"relatedCreatureIds",d.relatedCreatureIds);return d;}private static void read(JSONObject j,String k,List<String>o){JSONArray a=j.optJSONArray(k);if(a!=null)for(int i=0;i<a.length();i++)o.add(a.optString(i));}}
